insert into public.modules (
  id, name, category, description, icon, color, is_active, display_order, tags, metadata, updated_at
)
select
  x.id, x.name, x.category, x.description, x.icon, x.color, x.is_active,
  x.display_order, coalesce(x.tags, '{}'::text[]), x.metadata, now()
from jsonb_to_record($seed${"id":"language-english-vocab","name":"Từ vựng tiếng Anh","category":"language","description":"Học từ, nghĩa, phiên âm IPA, loại từ và câu ví dụ theo 20 chủ đề thiết thực.","icon":"languages","color":"#ec4899","is_active":true,"display_order":6,"tags":[],"metadata":{"subtitle":"200 từ nền tảng A1–A2","status":"available"},"updated_at":"2026-09-11T06:46:13.429Z"}$seed$::jsonb) as x(
  id text, name text, category text, description text, icon text, color text,
  is_active boolean, display_order integer, tags text[], metadata jsonb
)
on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description,
  icon = excluded.icon,
  color = excluded.color,
  is_active = excluded.is_active,
  display_order = excluded.display_order,
  tags = excluded.tags,
  metadata = excluded.metadata,
  updated_at = now();

