Z"},{"module_id":"language-english-vocab","id":"vocab-199","code":"box","name":"hộp","subname":"/bɒks/","image_url":null,"audio_url":null,"group_id":"daily-objects","tags":[],"attributes":{"id":"vocab-199","word":"box","pronunciation":"/bɒks/","partOfSpeech":"noun","vietnameseMeaning":"hộp","example":"The shoes are inside the box.","exampleTranslation":"Đôi giày ở trong hộp.","topicId":"daily-objects","level":"A2","imagePath":"vocab-199.webp","sortOrder":198},"sort_order":198,"updated_at":"2026-09-11T06:46:13.429Z"},{"module_id":"language-english-vocab","id":"vocab-200","code":"light","name":"đèn","subname":"/laɪt/","image_url":null,"audio_url":null,"group_id":"daily-objects","tags":[],"attributes":{"id":"vocab-200","word":"light","pronunciation":"/laɪt/","partOfSpeech":"noun","vietnameseMeaning":"đèn","example":"Please turn off the light.","exampleTranslation":"Vui lòng tắt đèn.","topicId":"daily-objects","level":"A2","imagePath":"vocab-200.webp","sortOrder":199},"sort_order":199,"updated_at":"2026-09-11T06:46:13.429Z"}]$seed$::jsonb) as x(
  module_id text, id text, code text, name text, subname text, image_url text,
  audio_url text, group_id text, tags text[], attributes jsonb, sort_order integer
)
on conflict (module_id, id) do update set
  code = excluded.code,
  name = excluded.name,
  subname = excluded.subname,
  image_url = coalesce(excluded.image_url, public.module_items.image_url),
  audio_url = coalesce(excluded.audio_url, public.module_items.audio_url),
  group_id = excluded.group_id,
  tags = excluded.tags,
  attributes = excluded.attributes ||
    case
      when public.module_items.image_url is not null
        then jsonb_build_object('imageUrl', public.module_items.image_url)
      else '{}'::jsonb
    end,
  sort_order = excluded.sort_order,
  updated_at = now();
